mapper.select:
SELECT fm.id, fm.field_name as item_name, fm.field_code as item_code, fm.parent_id as pid, fm.field_sort as item_order, fmf.file_url FROM safety_field_manage fm LEFT JOIN ytsafety_field_manage_file fmf ON fm.id = fmf.id WHERE delete_falg = 0 AND (field_type = #{itemCode} OR parent_id = #{id})
AND field_type = #{fieldType}
ORDER BY field_sort ASC;
